// ==================== HELPERS ====================
export function getDealTypeBySlug(slug: string): DealTypeData | undefined {
  return DEAL_TYPES[slug]
}

export function getAllDealTypeSlugs(): string[] {
  return Object.keys(DEAL_TYPES)
}

export function getProductCategoryBySlug(slug: string): ProductCategoryData | undefined {
  return PRODUCT_CATEGORIES[slug]
}

export function getAllProductCategorySlugs(): string[] {
  return Object.keys(PRODUCT_CATEGORIES)
}

export function getDealPageBySlug(slug: string): { type: 'deal-type' | 'product'; data: DealTypeData | ProductCategoryData } | undefined {
  const dealType = DEAL_TYPES[slug]
  if (dealType) return { type: 'deal-type', data: dealType }
  const productCat = PRODUCT_CATEGORIES[slug]
  if (productCat) return { type: 'product', data: productCat }
  return undefined
}

export function getAllDealPageSlugs(): string[] {
  return [...Object.keys(DEAL_TYPES), ...Object.keys(PRODUCT_CATEGORIES)]
}
